from pathlib import Path

p=Path('android-app/app/src/main/java/br/com/professor100destino/docenciafacil/MainActivity.java')
s=p.read_text(encoding='utf-8')

# O Professor Control deve sempre recarregar uma WebView limpa quando a Activity for recriada.
# O armazenamento local permanece no mesmo pacote Android; apenas o DOM/WebView antigo não é restaurado.
# O SIAP pode manter sua WebView separada quando estava em uso.
old_end_create='''        CookieManager cm=CookieManager.getInstance();\n        cm.setAcceptCookie(true); cm.setAcceptThirdPartyCookies(siapWeb,true);\n        showProfessor();\n    }\n\n    @Override protected void onActivityResult'''
new_end_create='''        CookieManager cm=CookieManager.getInstance();\n        cm.setAcceptCookie(true); cm.setAcceptThirdPartyCookies(siapWeb,true);\n\n        boolean restored=false;\n        if(b!=null){\n            try{\n                shellTarget=b.getString("shellTarget","auto");\n                int mode=b.getInt("activeMode",0);\n                if(mode==2){\n                    Bundle siapState=b.getBundle("siapWebState");\n                    if(siapState!=null)siapWeb.restoreState(siapState);\n                    uiWeb.setVisibility(View.GONE);\n                    siapWeb.setVisibility(View.VISIBLE);\n                    siteTop.setVisibility(View.VISIBLE);\n                    siteTitle.setText(b.getString("siteTitle","SIAP Fácil"));\n                    siteSub.setText(b.getString("siteSub",""));\n                    restored=true;\n                }\n            }catch(Exception ignored){}\n        }\n        // Nunca restaura uiWebState: uma página/DOM congelado não pode bloquear novamente o login.\n        if(!restored)showProfessor();\n    }\n\n    @Override protected void onActivityResult'''
if old_end_create in s:
    s=s.replace(old_end_create,new_end_create,1)

# Métodos de ciclo de vida e fechamento explícito.
marker='''    private void toggleOrientation(){int c=getResources().getConfiguration().orientation;setRequestedOrientation(c==Configuration.ORIENTATION_LANDSCAPE?ActivityInfo.SCREEN_ORIENTATION_PORTRAIT:ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE);}\n'''
methods='''    private void moveAppToBackground(){\n        try{moveTaskToBack(true);}catch(Exception e){}\n    }\n\n    private void closeAppNow(){\n        try{\n            if(Build.VERSION.SDK_INT>=Build.VERSION_CODES.LOLLIPOP)finishAndRemoveTask();\n            else finish();\n        }catch(Exception e){finish();}\n    }\n\n    private void backupAndClose(){\n        if(uiWeb==null){closeAppNow();return;}\n        try{\n            uiWeb.evaluateJavascript("(function(){try{return !!(window.professorControlBackupForExit&&window.professorControlBackupForExit());}catch(e){return false;}})();",value->{\n                String v=value==null?"":value.replace("\\\"","").trim();\n                if("true".equalsIgnoreCase(v)){\n                    Toast.makeText(MainActivity.this,"Backup salvo. Fechando o aplicativo...",Toast.LENGTH_SHORT).show();\n                    closeAppNow();\n                }else{\n                    Toast.makeText(MainActivity.this,"O backup não foi salvo. O aplicativo continuará aberto.",Toast.LENGTH_LONG).show();\n                }\n            });\n        }catch(Exception e){\n            Toast.makeText(this,"Não foi possível fazer o backup. O aplicativo continuará aberto.",Toast.LENGTH_LONG).show();\n        }\n    }\n\n    private void requestCloseInternal(){\n        runOnUiThread(()->{\n            new android.app.AlertDialog.Builder(MainActivity.this)\n                .setTitle("Fechar Docência Fácil")\n                .setMessage("Deseja fazer um backup antes de fechar o aplicativo?")\n                .setPositiveButton("Fazer backup e fechar",(d,w)->backupAndClose())\n                .setNegativeButton("Fechar sem backup",(d,w)->closeAppNow())\n                .setNeutralButton("Cancelar",null)\n                .show();\n        });\n    }\n\n    private void handleProfessorBack(){\n        if(uiWeb==null){moveAppToBackground();return;}\n        try{\n            uiWeb.evaluateJavascript("(function(){try{return !!(window.professorControlHandleBack&&window.professorControlHandleBack());}catch(e){return false;}})();",value->{\n                String v=value==null?"":value.replace("\\\"","").trim();\n                if(!"true".equalsIgnoreCase(v))moveAppToBackground();\n            });\n        }catch(Exception e){moveAppToBackground();}\n    }\n\n    @Override protected void onSaveInstanceState(Bundle outState){\n        try{\n            // Não salva/restaura o DOM do Professor Control. O localStorage continua preservado pelo WebView.\n            Bundle siapState=new Bundle();\n            if(siapWeb!=null)siapWeb.saveState(siapState);\n            outState.putBundle("siapWebState",siapState);\n            outState.putString("shellTarget",shellTarget);\n            int mode=(siapWeb!=null&&siapWeb.getVisibility()==View.VISIBLE)?2:1;\n            outState.putInt("activeMode",mode);\n            if(siteTitle!=null)outState.putString("siteTitle",String.valueOf(siteTitle.getText()));\n            if(siteSub!=null)outState.putString("siteSub",String.valueOf(siteSub.getText()));\n        }catch(Exception ignored){}\n        super.onSaveInstanceState(outState);\n    }\n\n'''
if 'private void requestCloseInternal()' not in s and marker in s:
    s=s.replace(marker,methods+marker,1)

# Ponte JS para o botão Fechar aplicativo.
bridge_marker='''        @JavascriptInterface public String orientationAction(){return MainActivity.this.orientationAction();}\n'''
bridge_add='''        @JavascriptInterface public void requestCloseApp(){requestCloseInternal();}\n        @JavascriptInterface public void sendToBackground(){runOnUiThread(()->moveAppToBackground());}\n'''
if '@JavascriptInterface public void requestCloseApp()' not in s and bridge_marker in s:
    s=s.replace(bridge_marker,bridge_marker+bridge_add,1)

# Voltar nunca encerra sozinho: volta ao menu/tela inicial ou envia para segundo plano.
old_back='''    @Override public void onBackPressed(){\n        if(siapWeb.getVisibility()==View.VISIBLE){showShell("menu");return;}\n        String u=uiWeb.getUrl();if(u!=null&&u.startsWith(SHELL_URL)){showProfessor();return;}if(uiWeb.canGoBack())uiWeb.goBack();else super.onBackPressed();\n    }\n'''
new_back='''    @Override public void onBackPressed(){\n        if(siapWeb!=null&&siapWeb.getVisibility()==View.VISIBLE){showShell("menu");return;}\n        String u=uiWeb!=null?uiWeb.getUrl():null;\n        if(u!=null&&u.startsWith(SHELL_URL)){showProfessor();return;}\n        handleProfessorBack();\n    }\n'''
if old_back in s:
    s=s.replace(old_back,new_back,1)

p.write_text(s,encoding='utf-8')
print('App lifecycle/background patch applied — Professor Control WebView is reloaded, not restored')